class ListNode {
  int val;
  ListNode next;

  ListNode(int x) {
    val = x;
  }
}

class Solution {
  public int kthToLast(ListNode head, int k) {
    ListNode fast = head, slow = head;
    for (int i = 0; i < k; i++) fast = fast.next;
    while (fast != null) {
      fast = fast.next;
      slow = slow.next;
    }
    return slow.val;
  }
}

class Solution:
    def kthToLast(self, head: ListNode, k: int) -> int:
        fast = slow = head
        for _ in range(k):
            fast = fast.next
        while fast:
            fast = fast.next
            slow = slow.next
        return slow.val

impl Solution {
  pub fn kth_to_last(head: Option<Box<ListNode>>, k: i32) -> i32 {
    let mut vals = vec![];
    let mut cur = head;
    while let Some(node) = cur {
      vals.push(node.val);
      cur = node.next;
    }
    vals[vals.len() - k as usize]
  }
}

const kthToLast = (head: ListNode | null, k: number): number => {
  let fast = head;
  let slow = head;
  for (let i = 0; i < k; i++) fast = fast!.next;
  while (fast) {
    fast = fast.next;
    slow = slow!.next;
  }
  return slow!.val;
};
